cd /c/Users/cooll/AppData/Local/Temp/frontier-hard-004-hard-004-run-001-9398e0-cgpk4y && cat > verify-fix.mjs << 'EOF'
import PQueue from './source/index.ts';

const queue = new PQueue({ concurrency: 1 });

// Fill the concurrency slot
const p1 = queue.add(async () => {
  await new Promise(r => setTimeout(r, 500));
  return 'task1';
});

// Add a task with a signal
const controller = new AbortController();
const p2 = queue.add(async () => 'task2', { signal: controller.signal });

// Abort the signal while task is queued
setTimeout(() => controller.abort(), 100);

// Verify p2 is rejected and removed from queue
p2.then(
  () => { console.log('FAIL: p2 resolved instead of rejecting'); process.exit(1); },
  () => console.log('PASS: p2 rejected with AbortError')
);

setTimeout(() => {
  console.log(`Queue size after abort: ${queue.size} (expected: 0)`);
  if (queue.size === 0) {
    console.log('PASS: Bug is fixed - queued task removed on abort');
  } else {
    console.log('FAIL: Bug still exists - queued task not removed');
    process.exit(1);
  }
}, 200);

await p1;
await queue.onIdle();
EOF
